export class TenantClient {
  private static readonly instances = new Map<string, TenantClient>();
  private constructor(public readonly tenant: string) {}

  static forTenant(tenant: string): TenantClient {
    let c = TenantClient.instances.get(tenant);
    if (!c) TenantClient.instances.set(tenant, (c = new TenantClient(tenant)));
    return c;
  }
}
